function initButtons() {
  document.querySelectorAll("[data-pp-button]").forEach(btn => {
    // ---------- DEFAULT CONFIG ----------

    // ---------- READ ATTRIBUTES (WITH FALLBACKS) ----------
    const type = btn.dataset.type || DEFAULTS.type;
    const label = btn.dataset.label || DEFAULTS.label;
    const bgColor = btn.dataset.bgcolor || DEFAULTS.bgColor;
    const textColor = btn.dataset.color || DEFAULTS.textColor;
    const fontFamily = btn.dataset.font || DEFAULTS.fontFamily;
    const fontSize = btn.dataset.fontsize || DEFAULTS.fontSize;
    const fontWeight = btn.dataset.fontweight || DEFAULTS.fontWeight;
    const onClickFn = btn.dataset.onclick;

    // ---------- CLASSES ----------
    btn.classList.add("pp-btn", `pp-btn-${type}`);

    // ---------- STYLES ----------
    btn.style.backgroundColor = bgColor;
    btn.style.color = textColor;
    btn.style.fontFamily = fontFamily;
    btn.style.fontSize = fontSize;
    btn.style.fontWeight = fontWeight;
    btn.style.minWidth = DEFAULTS.minWidth;
    btn.style.height = DEFAULTS.height;
    btn.style.padding = DEFAULTS.padding;
    btn.style.border = "none";
    btn.style.borderRadius = DEFAULTS.borderRadius;
    btn.style.cursor = DEFAULTS.cursor;

    // ---------- LABEL ----------
    btn.textContent = label;

    // ---------- ONCLICK (SAFE HANDLER) ----------
    if (onClickFn && typeof window[onClickFn] === "function") {
      btn.addEventListener("click", window[onClickFn]);
    }
  });
}
function initInputs() {
  document.querySelectorAll("[data-pp-input]").forEach(input => {
    const type = input.dataset.type || DEFAULTS.inputType;
    const placeholder =
      input.dataset.placeholder || DEFAULTS.inputPlaceholder;
    const onChangeFn = input.dataset.onchange;

    // Attributes
    input.type = type;
    input.placeholder = placeholder;
  

    // Styles (from DEFAULTS) — allow per-instance override via data-width / data-height
    input.style.width = input.dataset.width || DEFAULTS.inputWidth;
    input.style.height = input.dataset.height || DEFAULTS.inputHeight;
    input.style.padding = DEFAULTS.inputPadding;
    input.style.fontFamily = DEFAULTS.inputFontFamily;
    input.style.fontSize = DEFAULTS.inputFontSize;
    input.style.fontWeight = DEFAULTS.inputFontWeight;
    input.style.color = input.dataset.color || DEFAULTS.inputTextColor;
    input.style.backgroundColor =
      input.dataset.bgcolor || DEFAULTS.inputBgColor;
    input.style.border = `1px solid ${
      input.dataset.bordercolor || DEFAULTS.inputBorderColor
    }`;
    input.style.borderRadius = DEFAULTS.inputBorderRadius;
    input.style.outline = "none";

    // Create error element (hidden by default)
    const errorEl = document.createElement("div");
    errorEl.style.color = input.dataset.errorcolor || "#d93025";
    errorEl.style.fontSize = input.dataset.errorfontsize || "12px";
    errorEl.style.marginTop = "6px";
    errorEl.style.display = "none";
    if (input.parentNode) input.parentNode.insertBefore(errorEl, input.nextSibling);

    // Focus styles
    input.addEventListener("focus", () => {
      input.style.borderColor = DEFAULTS.inputFocusBorderColor;
    });

    input.addEventListener("blur", () => {
      // validate on blur
      validate();
      input.style.borderColor =
        input.dataset.bordercolor || DEFAULTS.inputBorderColor;
    });

    // Live validation on input
    input.addEventListener("input", () => {
      validate();
    });

    function showError(msg) {
      errorEl.textContent = msg;
      errorEl.style.display = "block";
      input.style.borderColor = input.dataset.errorborder || "#d93025";
    }

    function hideError() {
      errorEl.textContent = "";
      errorEl.style.display = "none";
      input.style.borderColor = input.dataset.bordercolor || DEFAULTS.inputBorderColor;
    }

    function validate() {
      const val = (input.value || "").trim();

      // required
      if (input.dataset.required === "true" && !val) {
        showError(input.dataset.requiredmessage || "This field is required");
        return false;
      }

      // type-based validations
      if (type === "email") {
        const re = /^\S+@\S+\.\S+$/;
        if (val && !re.test(val)) {
          showError(input.dataset.errormessage || input.dataset.error || "Please enter a valid email address");
          return false;
        }
      }

      if (type === "password") {
        const min = parseInt(input.dataset.minlength || input.dataset.minLength || "8", 10);
        if (val && val.length < min) {
          showError(input.dataset.errormessage || `Password must be at least ${min} characters`);
          return false;
        }
      }

      if (type === "pincode") {
        const len = parseInt(input.dataset.length || input.dataset.len || "6", 10);
        const pinRe = new RegExp(`^\\d{${len}}$`);
        if (val && !pinRe.test(val)) {
          showError(input.dataset.errormessage || `Pincode must be ${len} digits`);
          return false;
        }
      }

      if (type === "mobile" || type === "phone") {
        const len = parseInt(input.dataset.length || input.dataset.len || "10", 10);
        const phoneRe = new RegExp(`^\\d{${len}}$`);
        if (val && !phoneRe.test(val)) {
          showError(input.dataset.errormessage || `Mobile number must be ${len} digits`);
          return false;
        }
      }

      hideError();
      return true;
    }

    // onchange (CSP-safe) — still call, but ensure validation runs first
    if (onChangeFn && typeof window[onChangeFn] === "function") {
      input.addEventListener("change", e => {
        const valid = validate();
        window[onChangeFn](e.target.value, e, valid);
      });
    }
  });
}
function initDropdowns() {
  document.querySelectorAll("[data-pp-dropdown]").forEach(select => {
    const optionsRaw = select.dataset.options;
    const onChangeFn = select.dataset.onchange;

    // Reset (safe re-init)
    select.innerHTML = "";

    /* =========================
       OPTIONS (ARRAY OR STRING)
    ========================= */
    let options = [];

    if (optionsRaw) {
      try {
        // Try parsing as JSON array
        const parsed = JSON.parse(optionsRaw);
        if (Array.isArray(parsed)) {
          options = parsed;
        }
      } catch (e) {
        // Fallback to comma-separated
        options = optionsRaw.split(",").map(o => o.trim());
      }
    }

    options.forEach(opt => {
      const optionEl = document.createElement("option");

      // Support value-label objects later if needed
      optionEl.value = opt;
      optionEl.textContent = opt;

      select.appendChild(optionEl);
    });

    /* =========================
       STYLES (FROM DEFAULTS)
    ========================= */
    select.style.width =
      select.dataset.width || DEFAULTS.dropdownWidth;

    select.style.height =
      select.dataset.height || DEFAULTS.dropdownHeight;

    select.style.padding =
      select.dataset.padding || DEFAULTS.dropdownPadding;

    select.style.fontFamily =
      select.dataset.fontfamily || DEFAULTS.dropdownFontFamily;

    select.style.fontSize =
      select.dataset.fontsize || DEFAULTS.dropdownFontSize;

    select.style.fontWeight =
      select.dataset.fontweight || DEFAULTS.dropdownFontWeight;

    select.style.color =
      select.dataset.color || DEFAULTS.dropdownTextColor;

    select.style.backgroundColor =
      select.dataset.bgcolor || DEFAULTS.dropdownBgColor;

    select.style.border = `1px solid ${
      select.dataset.bordercolor || DEFAULTS.dropdownBorderColor
    }`;

    select.style.borderRadius =
      select.dataset.borderradius || DEFAULTS.dropdownBorderRadius;

    select.style.cursor =
      select.dataset.cursor || DEFAULTS.dropdownCursor;

    select.style.outline = "none";

    /* =========================
       FOCUS HANDLING
    ========================= */
    select.addEventListener("focus", () => {
      select.style.borderColor =
        DEFAULTS.dropdownFocusBorderColor;
    });

    select.addEventListener("blur", () => {
      select.style.borderColor =
        select.dataset.bordercolor || DEFAULTS.dropdownBorderColor;
    });

    /* =========================
       onchange (CSP-safe)
    ========================= */
    if (onChangeFn && typeof window[onChangeFn] === "function") {
      select.addEventListener("change", e =>
        window[onChangeFn](e.target.value, e)
      );
    }
  });
}
function initRadios() {
  document.querySelectorAll("[data-pp-radio-group]").forEach(group => {
    const optionsRaw = group.dataset.options;
    const name = group.dataset.name || `pp-radio-${Math.random()}`;
    const onChangeFn = group.dataset.onchange;
    const layout = (group.dataset.layout || "column").toLowerCase();

    /* =========================
       GROUP LAYOUT
       Supports data-layout="row" or "column". Defaults to column.
    ========================= */
    group.style.display = "flex";
    if (layout === "row") {
      group.style.flexDirection = "row";
      group.style.flexWrap = "wrap";
      group.style.columnGap = DEFAULTS.radioGroupGap;
      group.style.rowGap = "0";
    } else {
      group.style.flexDirection = "column";
      group.style.flexWrap = "nowrap";
      group.style.rowGap = DEFAULTS.radioGroupGap;
      group.style.columnGap = "0";
    }

    // Reset (safe re-init)
    group.innerHTML = "";

    /* =========================
       OPTIONS (ARRAY OR STRING)
    ========================= */
    let options = [];

    if (optionsRaw) {
      try {
        const parsed = JSON.parse(optionsRaw);
        if (Array.isArray(parsed)) {
          options = parsed;
        }
      } catch {
        options = optionsRaw.split(",").map(o => o.trim());
      }
    }

    /* =========================
       RADIO RENDERING
    ========================= */
    options.forEach(opt => {
      const wrapper = document.createElement("label");
      wrapper.style.display = "flex";
      wrapper.style.alignItems = "center";
      wrapper.style.cursor = DEFAULTS.radioCursor;
      wrapper.style.fontFamily = DEFAULTS.radioFontFamily;
      wrapper.style.fontSize = DEFAULTS.radioFontSize;
      wrapper.style.fontWeight = DEFAULTS.radioFontWeight;
      wrapper.style.color = DEFAULTS.radioTextColor;

      // spacing between radio + text
      wrapper.style.marginRight =
        layout === "row" ? DEFAULTS.radioGroupGap : "0";

      const radio = document.createElement("input");
      radio.type = "radio";
      radio.name = name;
      radio.value = opt;
      radio.style.marginRight = DEFAULTS.radioGap;
      radio.style.cursor = DEFAULTS.radioCursor;

      // onchange (CSP-safe)
      if (onChangeFn && typeof window[onChangeFn] === "function") {
        radio.addEventListener("change", e => {
          if (e.target.checked) {
            window[onChangeFn](e.target.value, e);
          }
        });
      }

      const text = document.createTextNode(opt);

      wrapper.appendChild(radio);
      wrapper.appendChild(text);
      group.appendChild(wrapper);
    });
  });
}
function initCheckboxes() {
  document.querySelectorAll("[data-pp-checkbox-group]").forEach(group => {
    const optionsRaw = group.dataset.options;
    const onChangeFn = group.dataset.onchange;
    const layout = group.dataset.layout || "column"; // NEW

    /* =========================
       GROUP LAYOUT
    ========================= */
    group.style.display = "flex";
    group.style.flexDirection = layout === "row" ? "row" : "column";
    group.style.flexWrap = layout === "row" ? "wrap" : "nowrap";
    group.style.gap = DEFAULTS.checkboxGroupGap;

    // Reset (safe re-init)
    group.innerHTML = "";

    /* =========================
       OPTIONS (ARRAY OR STRING)
    ========================= */
    let options = [];

    if (optionsRaw) {
      try {
        const parsed = JSON.parse(optionsRaw);
        if (Array.isArray(parsed)) {
          options = parsed;
        }
      } catch {
        options = optionsRaw.split(",").map(o => o.trim());
      }
    }

    /* =========================
       CHECKBOX RENDERING
    ========================= */
    options.forEach(opt => {
      const wrapper = document.createElement("label");
      wrapper.style.display = "flex";
      wrapper.style.alignItems = "center";
      wrapper.style.cursor = DEFAULTS.checkboxCursor;
      wrapper.style.fontFamily = DEFAULTS.checkboxFontFamily;
      wrapper.style.fontSize = DEFAULTS.checkboxFontSize;
      wrapper.style.fontWeight = DEFAULTS.checkboxFontWeight;
      wrapper.style.color = DEFAULTS.checkboxTextColor;

      // spacing between options when row layout
      wrapper.style.marginRight =
        layout === "row" ? DEFAULTS.checkboxGroupGap : "0";

      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.value = opt;
      checkbox.style.marginRight = DEFAULTS.checkboxGap;
      checkbox.style.cursor = DEFAULTS.checkboxCursor;

      /* =========================
         onchange (CSP-safe)
      ========================= */
      if (onChangeFn && typeof window[onChangeFn] === "function") {
        checkbox.addEventListener("change", e => {
          const checkedValues = Array.from(
            group.querySelectorAll("input[type='checkbox']:checked")
          ).map(cb => cb.value);

          window[onChangeFn](checkedValues, e);
        });
      }

      const text = document.createTextNode(opt);

      wrapper.appendChild(checkbox);
      wrapper.appendChild(text);
      group.appendChild(wrapper);
    });
  });
}
function initDatepicker() {
  document.querySelectorAll("[data-pp-datepicker]").forEach(input => {
    const onChangeFn = input.dataset.onchange;

    /* =========================
       ATTRIBUTES
    ========================= */
    input.type = DEFAULTS.dateInputType;

    // Disable previous dates
    const today = new Date();
    const yyyy = today.getFullYear();
    const mm = String(today.getMonth() + 1).padStart(2, "0");
    const dd = String(today.getDate()).padStart(2, "0");

    input.min = `${yyyy}-${mm}-${dd}`;

     /* =========================
       STYLES (FROM DEFAULTS ONLY) - allow instance overrides
     ========================= */
     input.style.width = input.dataset.width || DEFAULTS.dateWidth;
     input.style.height = input.dataset.height || DEFAULTS.dateHeight;
    input.style.padding = DEFAULTS.datePadding;
    input.style.fontFamily = DEFAULTS.dateFontFamily;
    input.style.fontSize = DEFAULTS.dateFontSize;
    input.style.fontWeight = DEFAULTS.dateFontWeight;
    input.style.color = input.dataset.color || DEFAULTS.dateTextColor;
    input.style.backgroundColor =
      input.dataset.bgcolor || DEFAULTS.dateBgColor;
    input.style.border = `1px solid ${
      input.dataset.bordercolor || DEFAULTS.dateBorderColor
    }`;
    input.style.borderRadius = DEFAULTS.dateBorderRadius;
    input.style.cursor = DEFAULTS.dateCursor;
    input.style.outline = "none";

    /* =========================
       FOCUS HANDLING
    ========================= */
    input.addEventListener("focus", () => {
      input.style.borderColor = DEFAULTS.dateFocusBorderColor;
    });

    input.addEventListener("blur", () => {
      input.style.borderColor =
        input.dataset.bordercolor || DEFAULTS.dateBorderColor;
    });

    /* =========================
       onchange (CSP-safe)
    ========================= */
    if (onChangeFn && typeof window[onChangeFn] === "function") {
      input.addEventListener("change", e =>
        window[onChangeFn](e.target.value, e)
      );
    }
  });
}
function initFileUpload() {
  document.querySelectorAll("[data-pp-file]").forEach(input => {
    const onChangeFn = input.dataset.onchange;
    const accept = input.dataset.accept;

    /* =========================
       MAX FILE SIZE (MB)
    ========================= */
    const maxSizeMB =
      parseInt(input.dataset.maxSize, 10) || DEFAULTS.fileMaxSizeMB;
    const maxSizeBytes = maxSizeMB * 1024 * 1024;


    /* =========================
       ATTRIBUTES
    ========================= */
    input.type = "file";
    if (accept) input.accept = accept;

    /* =========================
       SINGLE / MULTI FILE CONTROL
    ========================= */
    const isMultiple = input.dataset.multiple === "true";
    isMultiple ? input.setAttribute("multiple", "") : input.removeAttribute("multiple");

    /* =========================
       ALIGNMENT WRAPPER (FIX)
    ========================= */
    const align = input.dataset.align || "left"; // left | center

    const wrapper = document.createElement("div");
    wrapper.style.display = "flex";
    wrapper.style.width = "100%";
    wrapper.style.height = DEFAULTS.fileInputHeight; // 🔑 key fix
    wrapper.style.justifyContent =
      align === "center" ? "center" : "flex-start";
    wrapper.style.alignItems = "center"; // 🔑 vertical centering

    input.parentNode.insertBefore(wrapper, input);
    wrapper.appendChild(input);

    /* =========================
       WIDTH OVERRIDE
    ========================= */
    const width = input.dataset.width || DEFAULTS.fileInputWidth;
    input.style.width = width;
    input.style.display = "inline-flex"; // 🔑 prevents baseline issue
    input.style.alignItems = "center";

    /* =========================
       STYLES (FROM DEFAULTS)
    ========================= */
    input.style.height = DEFAULTS.fileInputHeight;
    input.style.lineHeight = DEFAULTS.fileInputHeight; // 🔑 key fix
    input.style.padding = DEFAULTS.fileInputPadding;
    input.style.borderRadius = DEFAULTS.fileInputBorderRadius;
    input.style.border = `1px solid ${DEFAULTS.fileInputBorderColor}`;
    input.style.backgroundColor = DEFAULTS.fileInputBgColor;
    input.style.color = DEFAULTS.fileInputTextColor;
    input.style.fontFamily = DEFAULTS.fileInputFontFamily;
    input.style.fontSize = DEFAULTS.fileInputFontSize;
    input.style.fontWeight = DEFAULTS.fileInputFontWeight;
    input.style.cursor = DEFAULTS.fileInputCursor;
    input.style.outline = "none";

    /* =========================
       ERROR MESSAGE
    ========================= */
    const errorEl = document.createElement("div");
    errorEl.style.color = DEFAULTS.fileErrorColor;
    errorEl.style.fontSize = DEFAULTS.fileErrorFontSize;
    errorEl.style.marginTop = DEFAULTS.fileErrorMarginTop;
    errorEl.style.display = "none";

    wrapper.appendChild(errorEl);

    /* =========================
       CHANGE HANDLER
    ========================= */
    input.addEventListener("change", e => {
      errorEl.style.display = "none";

      const files = Array.from(e.target.files);
      const invalidFile = files.find(f => f.size > maxSizeBytes);

      if (invalidFile) {
        errorEl.textContent = `File "${invalidFile.name}" exceeds ${maxSizeMB} MB limit`;
        errorEl.style.display = "block";
        input.value = "";
        return;
      }

      if (onChangeFn && typeof window[onChangeFn] === "function") {
        window[onChangeFn](files, e);
      }
    });
  });
}
/* ======================================================
   SHARED INPUT STYLE HELPER
   ====================================================== */
function applyInputStyles(input, overrides = {}) {
  input.style.height =
    overrides.height || DEFAULTS.tableInputHeight;
  input.style.padding =
    overrides.padding || DEFAULTS.tableInputPadding;
  input.style.border = `1px solid ${
    overrides.borderColor || DEFAULTS.tableInputBorderColor
  }`;
  input.style.borderRadius =
    overrides.borderRadius || DEFAULTS.tableInputBorderRadius;
  input.style.fontSize =
    overrides.fontSize || DEFAULTS.tableInputFontSize;
  input.style.outline = "none";

  input.addEventListener("focus", () => {
    input.style.borderColor =
      overrides.focusBorderColor ||
      DEFAULTS.tableInputFocusBorderColor;
  });

  input.addEventListener("blur", () => {
    input.style.borderColor =
      overrides.borderColor || DEFAULTS.tableInputBorderColor;
  });
}

function getAttr(el, attr, defaultValue) {
  return el.dataset[attr] !== undefined
    ? el.dataset[attr]
    : defaultValue;
}


/* ======================================================
   TABLE COMPONENT
   ====================================================== */
function initTables() {
  document.querySelectorAll("[data-pp-table]").forEach(container => {
    const dataSourceName = container.dataset.datasource;
    const data = window[dataSourceName];

    if (!Array.isArray(data) || data.length === 0) {
      container.innerHTML = "<p>No data available</p>";
      return;
    }

    /* ===== CONFIG ===== */
    const config = {
      pageSize: parseInt(container.dataset.pageSize || "5", 10),
      stickyHeader: container.dataset.stickyHeader !== "false",
      columnToggle: container.dataset.columnToggle !== "false",
      enableSearch: container.dataset.search !== "false",

      width: getAttr(container, "width", DEFAULTS.tableWidth),
      fontFamily: getAttr(container, "fontFamily", DEFAULTS.tableFontFamily),
      fontSize: getAttr(container, "fontSize", DEFAULTS.tableFontSize),
      textColor: getAttr(container, "textColor", DEFAULTS.tableTextColor),
      borderColor: getAttr(container, "borderColor", DEFAULTS.tableBorderColor),
      headerBg: getAttr(container, "headerBg", DEFAULTS.tableHeaderBg),
      headerTextColor: getAttr(container, "headerTextColor", DEFAULTS.tableHeaderTextColor),
      rowHoverBg: getAttr(container, "rowHoverBg", DEFAULTS.tableRowHoverBg),
      searchPlaceholder: getAttr(container, "searchPlaceholder", DEFAULTS.searchPlaceholder)
    };

    const columns = Object.keys(data[0]);
    let visibleColumns = [...columns];
    let filteredData = [...data];

    let currentPage = 1;
    let sortColumn = null;
    let sortDirection = "asc";

    container.innerHTML = "";
    container.style.fontFamily = config.fontFamily;
    container.style.fontSize = config.fontSize;
    container.style.color = config.textColor;

    /* ================= TOP BAR ================= */
    const topBar = document.createElement("div");
    topBar.style.display = "flex";
    topBar.style.justifyContent = "space-between";
    topBar.style.alignItems = "center";
    topBar.style.marginBottom = "10px";

    const leftBar = document.createElement("div");
    const rightBar = document.createElement("div");

    topBar.appendChild(leftBar);
    topBar.appendChild(rightBar);
    container.appendChild(topBar);

    /* ========== SEARCH (RIGHT) ========== */
    if (config.enableSearch) {
      const searchInput = document.createElement("input");
      searchInput.placeholder = config.searchPlaceholder;
      applyInputStyles(searchInput);
      searchInput.style.minWidth = "220px";

      searchInput.addEventListener("input", e => {
        const val = e.target.value.toLowerCase();
        filteredData = data.filter(row =>
          columns.some(col =>
            String(row[col]).toLowerCase().includes(val)
          )
        );
        currentPage = 1;
        applySorting();
        renderTable();
      });

      rightBar.appendChild(searchInput);
    }

    /* ================= TABLE ================= */
    const tableWrapper = document.createElement("div");
    tableWrapper.style.maxHeight = "360px";
    tableWrapper.style.overflow = "auto";

    const table = document.createElement("table");
    table.style.width = "100%";
    table.style.borderCollapse = "collapse";

    tableWrapper.appendChild(table);
    container.appendChild(tableWrapper);

    /* ================= PAGINATION ================= */
    const pagination = document.createElement("div");
    pagination.style.display = "flex";
    pagination.style.justifyContent = "flex-end";
    pagination.style.alignItems = "center";
    pagination.style.gap = "6px";
    pagination.style.marginTop = "10px";
    container.appendChild(pagination);

    /* ================= SORTING ================= */
    function applySorting() {
      if (!sortColumn) return;

      filteredData.sort((a, b) => {
        const A = a[sortColumn];
        const B = b[sortColumn];

        if (!isNaN(A) && !isNaN(B)) {
          return sortDirection === "asc" ? A - B : B - A;
        }

        return sortDirection === "asc"
          ? String(A).localeCompare(String(B))
          : String(B).localeCompare(String(A));
      });
    }

    function toggleSort(col) {
      if (sortColumn === col) {
        sortDirection = sortDirection === "asc" ? "desc" : "asc";
      } else {
        sortColumn = col;
        sortDirection = "asc";
      }
      applySorting();
      renderTable();
    }

    /* ================= RENDER ================= */
    function renderTable() {
      table.innerHTML = "";
      pagination.innerHTML = "";

      const start = (currentPage - 1) * config.pageSize;
      const pageData = filteredData.slice(start, start + config.pageSize);

      /* HEADER */
      const thead = document.createElement("thead");
      const headerRow = document.createElement("tr");

      visibleColumns.forEach(col => {
        const th = document.createElement("th");
        th.textContent =
          col +
          (sortColumn === col
            ? sortDirection === "asc"
              ? " ▲"
              : " ▼"
            : "");

        th.style.padding = DEFAULTS.tablePadding;
        th.style.border = `1px solid ${config.borderColor}`;
        th.style.background = config.headerBg;
        th.style.color = config.headerTextColor;
        th.style.cursor = "pointer";
        th.style.userSelect = "none";
        th.style.position = config.stickyHeader ? "sticky" : "";
        th.style.top = config.stickyHeader ? "0" : "";
        th.style.textTransform="capitalize"

        th.addEventListener("click", () => toggleSort(col));
        headerRow.appendChild(th);
      });

      thead.appendChild(headerRow);
      table.appendChild(thead);

      /* BODY */
      const tbody = document.createElement("tbody");

      pageData.forEach(row => {
        const tr = document.createElement("tr");

        tr.addEventListener("mouseenter", () => {
          tr.style.background = config.rowHoverBg;
        });
        tr.addEventListener("mouseleave", () => {
          tr.style.background = "";
        });

        visibleColumns.forEach(col => {
          const td = document.createElement("td");
          td.textContent = row[col];
          td.style.padding = DEFAULTS.tablePadding;
          td.style.border = `1px solid ${config.borderColor}`;
          tr.appendChild(td);
        });

        tbody.appendChild(tr);
      });

      table.appendChild(tbody);

      /* PAGINATION UI */
      const totalPages = Math.ceil(filteredData.length / config.pageSize);

      const prevBtn = document.createElement("button");
      prevBtn.textContent = "Prev";
      stylePageButton(prevBtn, currentPage === 1);
      prevBtn.onclick = () => {
        if (currentPage > 1) {
          currentPage--;
          renderTable();
        }
      };

      const nextBtn = document.createElement("button");
      nextBtn.textContent = "Next";
      stylePageButton(nextBtn, currentPage === totalPages);
      nextBtn.onclick = () => {
        if (currentPage < totalPages) {
          currentPage++;
          renderTable();
        }
      };

      const pageInfo = document.createElement("span");
      pageInfo.textContent = `Page ${currentPage} of ${totalPages}`;
      pageInfo.style.margin = "0 6px";

      pagination.appendChild(prevBtn);
      pagination.appendChild(pageInfo);
      pagination.appendChild(nextBtn);
    }

    function stylePageButton(btn, disabled) {
      btn.disabled = disabled;
      btn.style.padding = "6px 12px";
      btn.style.borderRadius = "4px";
      btn.style.border = "1px solid #ccc";
      btn.style.cursor = disabled ? "not-allowed" : "pointer";
      btn.style.background = disabled ? "#f2f2f2" : "#fff";
    }

    renderTable();
  });
}

﻿function initModal() {
  // Render shorthand holders: <div data-pp-modal ...></div>
  document.querySelectorAll("[data-pp-modal]").forEach(wrapper => {
    const modalId = wrapper.dataset.id || `pp-modal-${Math.random().toString(36).slice(2)}`;
    const triggerText = wrapper.dataset.triggerText || "Open Modal";
    const title = wrapper.dataset.title || "";
    const contentText = wrapper.dataset.content || "";
    const triggerBg = wrapper.dataset.triggerBg || "#FFA500";
    const triggerPadding = wrapper.dataset.triggerPadding || "10px 20px";
    const triggerFontSize = wrapper.dataset.triggerFontsize || "16px";
    const triggerMarginTop = wrapper.dataset.triggerMarginTop || "0px";

    // avoid destroying existing content if user placed a trigger
    let trigger = wrapper.querySelector('[data-pp-modal-trigger]');
    if (!trigger) {
      trigger = document.createElement("button");
      trigger.type = "button";
      trigger.textContent = triggerText;
      trigger.style.cursor = "pointer";
      trigger.style.backgroundColor = triggerBg;
      trigger.style.padding = triggerPadding;
      trigger.style.fontSize = triggerFontSize;
      trigger.style.marginTop = triggerMarginTop;
      trigger.style.color = "#fff";
      trigger.style.border = "none";
      trigger.style.borderRadius = "6px";
      wrapper.appendChild(trigger);
    }
    trigger.setAttribute('data-pp-modal-trigger', '');
    trigger.dataset.target = modalId;

    // create modal element if missing
    if (!document.getElementById(modalId)) {
      const modal = document.createElement("div");
      modal.id = modalId;
      modal.style.display = "none";
      modal.style.position = "fixed";
      modal.style.top = "0";
      modal.style.left = "0";
      modal.style.width = "100%";
      modal.style.height = "100%";
      modal.style.backgroundColor = "rgba(0,0,0,0.5)";
      modal.style.display = "none";
      modal.style.flexDirection = "column";
      modal.style.justifyContent = "center";
      modal.style.alignItems = "center";
      modal.style.zIndex = "1000";

      const modalContent = document.createElement("div");
      modalContent.className = "pp-modal-content";
      modalContent.style.background = "#fff";
      modalContent.style.padding = "20px";
      modalContent.style.borderRadius = "8px";
      modalContent.style.maxWidth = "500px";
      modalContent.style.width = "90%";

      if (title) {
        const h2 = document.createElement("h2");
        h2.textContent = title;
        modalContent.appendChild(h2);
      }

      if (contentText) {
        const p = document.createElement("p");
        p.textContent = contentText;
        modalContent.appendChild(p);
      }

      const closeBtn = document.createElement("button");
      closeBtn.textContent = "Close";
      closeBtn.setAttribute("data-pp-modal-close", "");
      modalContent.appendChild(closeBtn);

      modal.appendChild(modalContent);
      document.body.appendChild(modal);
    }
  });

  // Bind behavior to all modal triggers (including ones created above)
  document.querySelectorAll("[data-pp-modal-trigger]").forEach(trigger => {
    const modalId = trigger.dataset.target;
    const modal = document.getElementById(modalId);
    if (!modal) return;

    const modalContent = modal.querySelector('.pp-modal-content');

    trigger.addEventListener('click', () => {
      modal.style.display = 'flex';
    });

    const closeBtn = modal.querySelector('[data-pp-modal-close]');
    if (closeBtn) closeBtn.addEventListener('click', () => (modal.style.display = 'none'));

    modal.addEventListener('click', e => {
      if (e.target === modal) modal.style.display = 'none';
    });
  });
}
function initSelectMenus() {
  document.querySelectorAll("[data-pp-select]").forEach(container => {
    const optionsRaw = container.dataset.options;
    const isMultiple = container.dataset.multiple === "true";
    const enableSearch = container.dataset.search === "true";
    const onChangeFn = container.dataset.onchange || container.dataset.onChange;
    const placeholder = container.dataset.placeholder || "Select";
    const searchPlaceholder =
      container.dataset.searchPlaceholder ||
      container.dataset.searchplaceholder ||
      "Search...";
    const width = container.dataset.width || DEFAULTS.dropdownWidth;

    // Highlight colors (inline → CSP safe)
    const ACTIVE_BG = "#eef3ff";
    const ACTIVE_FONT_WEIGHT = "500";

    container.innerHTML = "";

    /* =========================
       OPTIONS
    ========================= */
    let options = [];
    try {
      options = JSON.parse(optionsRaw);
    } catch {
      options = optionsRaw.split(",").map(o => o.trim());
    }

    /* =========================
       STATE
    ========================= */
    const selectedValues = new Set();
    let singleSelectedValue = null;

    /* =========================
       WRAPPER
    ========================= */
    const wrapper = document.createElement("div");
    wrapper.classList.add("pp-select-wrapper");
    wrapper.style.position = "relative";
    wrapper.style.width = width;

    /* =========================
       DISPLAY FIELD
    ========================= */
    const display = document.createElement("div");
    display.textContent = placeholder;
    display.style.padding = DEFAULTS.dropdownPadding;
    display.style.border = `1px solid ${DEFAULTS.dropdownBorderColor}`;
    display.style.borderRadius = DEFAULTS.dropdownBorderRadius;
    display.style.cursor = "pointer";
    display.style.backgroundColor = DEFAULTS.dropdownBgColor;
    display.style.fontFamily = DEFAULTS.dropdownFontFamily;
    display.style.fontSize = DEFAULTS.dropdownFontSize;

    /* =========================
       DROPDOWN MENU
    ========================= */
    const menu = document.createElement("div");
    menu.style.position = "absolute";
    menu.style.top = "100%";
    menu.style.left = "0";
    menu.style.right = "0";
    menu.style.border = `1px solid ${DEFAULTS.dropdownBorderColor}`;
    menu.style.backgroundColor = "#fff";
    menu.style.borderRadius = DEFAULTS.dropdownBorderRadius;
    menu.style.zIndex = "1000";
    menu.style.display = "none";
    menu.style.maxHeight = "240px";
    menu.style.overflowY = "auto";

    // Prevent menu click from closing
    menu.addEventListener("click", e => e.stopPropagation());

    /* =========================
       SEARCH INPUT
    ========================= */
    let searchInput;
    if (enableSearch) {
      searchInput = document.createElement("input");
      searchInput.placeholder = searchPlaceholder;
      searchInput.style.width = "100%";
      searchInput.style.padding = "8px 12px";
      searchInput.style.border = "none";
      searchInput.style.borderBottom = "1px solid #ddd";
      searchInput.style.outline = "none";
      searchInput.style.fontSize = DEFAULTS.dropdownFontSize;

      searchInput.addEventListener("click", e => e.stopPropagation());
      searchInput.addEventListener("keydown", e => e.stopPropagation());

      menu.appendChild(searchInput);
    }

    /* =========================
       OPTION LIST
    ========================= */
    const optionBox = document.createElement("div");

    options.forEach(opt => {
      const row = document.createElement("div");
      row.dataset.value = opt.toLowerCase();
      row.style.display = "flex";
      row.style.alignItems = "center";
      row.style.padding = "8px 12px";
      row.style.cursor = "pointer";
      row.style.fontFamily = DEFAULTS.dropdownFontFamily;
      row.style.fontSize = DEFAULTS.dropdownFontSize;

      let checkbox;

      if (isMultiple) {
        checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.value = opt;
        checkbox.style.marginRight = "8px";
        row.appendChild(checkbox);
      }

      row.appendChild(document.createTextNode(opt));

      row.addEventListener("click", () => {
        if (isMultiple) {
          checkbox.checked = !checkbox.checked;

          checkbox.checked
            ? selectedValues.add(opt)
            : selectedValues.delete(opt);

          row.style.backgroundColor = checkbox.checked ? ACTIVE_BG : "";

          display.textContent =
            selectedValues.size > 0
              ? Array.from(selectedValues).join(", ")
              : placeholder;

          if (onChangeFn && typeof window[onChangeFn] === "function") {
            window[onChangeFn](Array.from(selectedValues));
          }
        } else {
          // Clear previous highlight
          [...optionBox.children].forEach(r => {
            r.style.backgroundColor = "";
            r.style.fontWeight = "normal";
          });

          singleSelectedValue = opt;
          display.textContent = opt;
          row.style.backgroundColor = ACTIVE_BG;
          row.style.fontWeight = ACTIVE_FONT_WEIGHT;

          menu.style.display = "none";

          if (onChangeFn && typeof window[onChangeFn] === "function") {
            window[onChangeFn](opt);
          }
        }
      });

      optionBox.appendChild(row);
    });

    /* =========================
       SEARCH FILTER
    ========================= */
    if (enableSearch) {
      searchInput.addEventListener("input", () => {
        const keyword = searchInput.value.toLowerCase().trim();
        [...optionBox.children].forEach(row => {
          row.style.display = row.dataset.value.includes(keyword)
            ? "flex"
            : "none";
        });
      });
    }

    menu.appendChild(optionBox);

    /* =========================
       OPEN / CLOSE
    ========================= */
    display.addEventListener("click", e => {
      e.stopPropagation();

      // Restore highlight for single select
      if (!isMultiple && singleSelectedValue) {
        [...optionBox.children].forEach(row => {
          const isActive =
            row.dataset.value === singleSelectedValue.toLowerCase();
          row.style.backgroundColor = isActive ? ACTIVE_BG : "";
          row.style.fontWeight = isActive ? ACTIVE_FONT_WEIGHT : "normal";
        });
      }

      menu.style.display = menu.style.display === "block" ? "none" : "block";
    });

    document.addEventListener("click", () => {
      menu.style.display = "none";
    });

    wrapper.appendChild(display);
    wrapper.appendChild(menu);
    container.appendChild(wrapper);
  });
}
window.PP_UI = {
  init() {
    if (typeof initButtons === "function") initButtons();
    if (typeof initInputs === "function") initInputs();
    if (typeof initDropdowns === "function") initDropdowns();
    if (typeof initRadios === "function") initRadios();
    if (typeof initCheckboxes === "function") initCheckboxes();
    if (typeof initDatepicker === "function") initDatepicker();
    if (typeof initFileUpload === "function") initFileUpload();
    if (typeof initSelectMenus === "function") initSelectMenus();
    if(typeof initTables==="function") initTables();
    if (typeof initModal === "function") initModal();
  }
};

document.addEventListener("DOMContentLoaded", () => {
  window.PP_UI.init();
});
